  ARRAY['/images/appleton_court_aerial_clean.jpg', '/images/appleton_court_exterior_real.jpg', '/images/appleton_court_interior_living.jpg', '/images/appleton_court_interior_stairs.jpg', '/images/IMG-20260919-WA0004 (1).jpg', '/images/IMG-20260919-WA0005 (1).jpg', '/images/IMG-20260919-WA0006.jpg'],
