  ARRAY['/images/appleton_enclave_entrance.jpg', '/images/yt_ihEzpBhqRjY.jpg'],
  'https://caihgroup.com/wp-content/uploads/2024/11/APPLETON-FORM-FAQ.pdf',
  NULL,
  ARRAY[]::TEXT[],
  '[{"plotSize":"300 sqm","initialDeposit":"₦3,000,000","threeMonths":"₦16,000,000","sixMonths":"₦18,000,000"},{"plotSize":"500 sqm","initialDeposit":"₦4,000,000","threeMonths":"₦25,000,000","sixMonths":"₦27,000,000"},{"plotSize":"1,000 sqm","initialDeposit":"₦10,000,000","threeMonths":"₦60,000,000","sixMonths":"₦65,000,000"}]'::jsonb,
  '{"accountName":"CAIH RESOURCES LIMITED","bankName":"TAJ BANK","accountNumber":"0008343786"}'::jsonb,
  '[{"question":"Where is APPLETON ENCLAVE located?","answer":"APPLETON ENCLAVE is located at Olomowewe area of the Free Trade Zone, with close proximity to the Dangote Refinery, Deep Sea port, and other notable developments. A very serene location with beautiful residential ambience."},{"question":"Who is the developer of APPLETON ENCLAVE?","answer":"CAIH Group (Caih Resources Limited)."},{"question":"What is the title on APPLETON ENCLAVE?","answer":"Certificate of Occupancy (C of O)."},{"question":"What plot sizes are available?","answer":"300sqm, 500sqm, and 1,000sqm respectively."},{"question":"What facilities will be available in the estate?","answer":"Well-paved road network, constant electricity, portable water, armed security personnel, children play area, and lavish greenery amongst others."},{"question":"What is the transaction process?","answer":"1. Pay the initial deposit. 2. Collect Receipt and Contract of Sale. 3. Collect Deed of Assignment and Survey Plan on completion of payment. 4. Collect Allocation Letter and Physical Allocation. 5. Commence your building."},{"question":"Are there any encumbrances on the land?","answer":"No, the land is free from every known government acquisition or interest and adverse claims."},{"question":"Can I pay cash to your consultants?","answer":"No! All payments for APPLETON ENCLAVE should be made directly to CAIH GROUP’S designated bank account: Caih Resources Limited, TAJ Bank, Account Number: 0008343786."},{"question":"How do I pay my balance after initial deposit?","answer":"Balance will be paid based on an agreed fixed monthly installment across the 0-3 months or 4-6 months duration."},{"question":"Is the price subject to change?","answer":"Yes."},{"question":"What documents will I get after initial deposit?","answer":"Receipt of payment and Contract of Sales."},{"question":"Can I resell my plot(s)?","answer":"Yes, plot(s) FULLY paid for can be resold, but with the company’s consent."},{"question":"When will work begin on the estate?","answer":"Infrastructure development work is currently ongoing."},{"question":"Can I start building immediately after payment?","answer":"Yes, construction can commence after full payment and after obtaining all Government Permits."},{"question":"Is the road leading to the estate motorable?","answer":"Yes, there is a good motorable road leading to the estate."}]'::jsonb
