-- 2. UPSERT BLOG ARTICLES (7 ARTICLES)
INSERT INTO public.articles (
  id, title, category, category_label, read_time, date, author,
  image, excerpt, content, sections, key_takeaways, featured
) VALUES (
  'why-lekki-phase-2-is-great',
  'Why Lekki Phase 2 is Great for New Homeowners & Investors',
  'property-market',
  'Property Market',
  '6 min read',
  'March 2025',
  '{"name":"Caih Group","avatarInitials":"CG","role":"Caih Group"}'::jsonb,
  'https://lh3.googleusercontent.com/aida-public/AB6AXuCaspKwS-9-lfkm8UrXHGs0LP0-yQHNTVOhS82m5hholmOgEnoA6tCljQbXGrDFnku0rxHqmgR-n85EN4St9AL0OQxquC714HDx4_1C_3EeSthYmjekcmXol8ZORImvnhHPVsMrFD55YRnGg0Rgu2pARRtSKgeJEpqwbXsEmQtp1XVUkWcp7E2i3btShJn-0IEiwkknUN3nlQph6c5fd1VuJg_PyaUl9cjn_mzBZ-AQInGpMDundR014g',
  'New dualized roads, serene gated communities, and favorable entry pricing make Lekki Phase 2 the top choice for families and diaspora investors seeking long-term value in Lagos.',
  ARRAY['The rapid infrastructural expansion along the Lekki-Epe corridor has fundamentally redefined property investment in Lagos. While Lekki Phase 1 has reached density saturation with premium pricing exceeding ₦350m–₦500m for standard residential units, Lekki Phase 2 has emerged as the premier corridor for discerning homeowners seeking institutional construction quality paired with sensible entry economics.', 'Key developmental drivers in this corridor include expanded drainage channels, uninterrupted arterial road links, modern underground utility piping, and proximity to major educational institutions, shopping plazas, and the emerging regional commercial nodes.', 'Unlike the congested inner city nodes, Lekki Phase 2 provides master-planned layouts designed for modern living. Generous setback spaces, dedicated green areas, wide pedestrian walkways, and gated security access ensure residents enjoy both tranquility and prestige.', 'For diaspora buyers and local corporate professionals, purchasing in gated master-planned communities like Appleton Enclave provides verified Governor’s Consent titles, professional facility management, and guaranteed equity growth over a 3 to 5-year investment horizon.'],
  '[{"heading":"1. The Price-to-Value Disparity Between Phase 1 and Phase 2","paragraphs":["In Lekki Phase 1, the cost per square meter has risen dramatically due to limited land availability and high commercial redevelopment pressure. Many homeowners now contend with commercial traffic, parking congestion, and mixed-zoning disruptions.","In contrast, Lekki Phase 2 offers pristine residential enclaves where property prices remain accessible while delivering equal or superior architectural finishes. Early purchasers in Phase 2 are experiencing annual capital appreciation rates of 22% to 28%, significantly outperforming traditional fixed-income returns in Nigeria."],"keyPoints":["Entry price point is 40% to 55% lower than comparable properties in Phase 1","Higher rental yields for 4-bedroom terraces and semi-detached homes (typically 9% to 12% gross yield)","Strict zoning enforcement that preserves peaceful residential environments"]},{"heading":"2. Infrastructure Catalysts Driving the Corridor","paragraphs":["The state government’s aggressive execution of the Lekki Regional Road, the expansion of the Lekki-Epe Expressway into a six-lane dual carriageway, and the ongoing development of the Lagos-Calabar Coastal Highway are unlocking unprecedented connectivity.","Commute times between Lekki Phase 2, Victoria Island, and the commercial hubs of Ikoyi are shortening steadily, making daily commuting painless for executive workers while preserving the privacy of family life at home."],"keyPoints":["Lekki Regional Road providing direct bypass routes to avoid highway bottlenecks","Modern covered concrete storm drainage channels preventing seasonal flooding","Underground electrical cabling and dedicated independent power plant (IPP) linkages"]},{"heading":"3. Strategic Proximity to the Lekki Free Trade Zone Hub","paragraphs":["Positioned between the established high-income island neighborhoods and the multibillion-dollar industrial corridor of Ibeju-Lekki (home to the Dangote Refinery, Lekki Deep Sea Port, and Kellogg’s manufacturing plants), Lekki Phase 2 serves as the primary residential hub for senior executives and engineers.","This dynamic creates a constant, recession-proof rental demand from expatriates, multinational contractors, and tech executives who seek secure, upscale housing within a 20-minute drive of their workplaces."]}]'::jsonb,
  ARRAY['Lekki Phase 2 offers high capital growth potential with 40-50% lower entry prices than Phase 1.', 'Major infrastructure like the Regional Road and Coastal Highway are cutting commute times to Victoria Island.', 'High rental demand from corporate executives working in Victoria Island and the Lekki Free Zone.', 'Master-planned communities like Appleton Enclave guarantee verified titles, reliable drainage, and 24/7 security.'],
  true
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  category = EXCLUDED.category,
  category_label = EXCLUDED.category_label,
  read_time = EXCLUDED.read_time,
  date = EXCLUDED.date,
  author = EXCLUDED.author,
  image = EXCLUDED.image,
  excerpt = EXCLUDED.excerpt,
  content = EXCLUDED.content,
  sections = EXCLUDED.sections,
  key_takeaways = EXCLUDED.key_takeaways,
  featured = EXCLUDED.featured,
  updated_at = NOW();

INSERT INTO public.articles (
  id, title, category, category_label, read_time, date, author,
  image, excerpt, content, sections, key_takeaways, featured
) VALUES (
  'how-to-buy-land-safely',
  'How to Buy Land or a Home in Lagos Safely (Complete Legal Due Diligence Guide)',
  'buying-tips',
  'Buying Tips',
  '7 min read',
  'Feb 24, 2025',
  '{"name":"Caih Group","avatarInitials":"CG","role":"Caih Group"}'::jsonb,
  'https://lh3.googleusercontent.com/aida-public/AB6AXuCnCZB9i3w6wY-79yplV3BsnJQDGuaMW_2RVge11NiznHJ0gZBg2H0evgEFiVqefXkN_OIoHKsj7Q7JoznSh9aVpvOpBqiVcnO9XLSj4o5XPoTheHl7SwR9ut_ABTGZi6NNeVMCUkyHvtn7dFoOlBPRoqXujhCc3513EwGwSwvjmBvOzD1XS7KuATqeuoF4239gBuJXTm9V3RAO_cm0mdQz2AIGfEvOkp8oqzoqLeZ5solI12E7kxsbvg',
  'Step-by-step verification checklist every buyer must follow to avoid fraud, verify land titles, and secure their real estate in Lagos.',
  ARRAY['Property acquisitions in Lagos require rigorous legal due diligence. The cornerstone of a bulletproof transaction is verifying the land classification at the Lagos State Lands Bureau in Alausa before any funds change hands.', 'Never rely on oral promises, informal community receipts, or unofficial agreements. Always demand certified true copies of the registered title—whether a Certificate of Occupancy (C of O), Governor’s Consent, or registered Gazette—and insist on independent coordinate charting through a certified surveyor.', 'First-time buyers and Nigerians living in the diaspora frequently fall victim to unverified land sales because they bypass formal search procedures. Choosing institutional developers with clean corporate standing and unencumbered root titles remains the safest path to property ownership in Lagos.', 'At Caih Group, every estate development is backed by validated, registered titles and clear transfer procedures, ensuring buyers own their properties with absolute legal security.'],
  '[{"heading":"Step 1: Obtain Survey Coordinates and Perform Official Charting","paragraphs":["Before negotiating price or signing preliminary receipts, collect the registered survey plan of the parcel. Have a registered surveyor extract the GPS coordinates (Pillar Numbers) and submit them for an official Land Information Certificate at the Office of the State Surveyor General in Alausa.","The charting report reveals whether the land is free from committed government acquisition, designated agricultural reserves, coastal road setbacks, or transmission corridors."],"keyPoints":["Verify that pillar numbers on the survey match the physical concrete beacons on ground","Confirm the land status is \"Free\" or covered by an approved Government Excision","Never purchase land categorized under \"Committed Government Acquisition\""]},{"heading":"Step 2: Conduct an Official Search at the Lands Registry","paragraphs":["Your solicitor must conduct a formal search at the Lagos State Lands Registry. This examination inspects the Register of Deeds to verify the root of title, ownership history, and whether any financial encumbrances exist.","A land parcel may appear legally sound on the surface but could be pledged as collateral for a commercial bank loan or entangled in ongoing probate litigation."],"keyPoints":["Confirm that the seller is the registered legal title holder or authorized power-of-attorney grantee","Inspect for registered mortgages, lis pendens (pending lawsuits), or court judgments","Verify that the property taxes and ground rents have been kept current"]},{"heading":"Step 3: Verify the Developer’s Corporate Registration & Track Record","paragraphs":["If purchasing from a real estate development firm, check the company’s corporate standing on the Corporate Affairs Commission (CAC) portal. Confirm the company’s active status, directors’ identities, and past delivery track record.","Reputable developers like Caih Group operate with registered corporate entities, transparent escrow agreements, and verifiable past estates that you can physically inspect."]},{"heading":"Step 4: Execute Valid Legal Documentation and File for Governor’s Consent","paragraphs":["Upon concluding the purchase, ensure you receive a comprehensive Contract of Sale, a signed and sealed Deed of Assignment, and the original Survey Plan. Your legal team must immediately submit the Deed of Assignment to Alausa for the Governor’s Consent and stamp duty payment.","Securing Governor’s Consent vests complete legal ownership in your name and protects your property against any future third-party claims."]}]'::jsonb,
  ARRAY['Always chart survey coordinates at the Surveyor General’s office before paying any deposit.', 'Verify the title at the Lands Registry in Alausa to ensure no bank liens or ongoing court cases.', 'Insist on a registered Deed of Assignment and process your Governor’s Consent promptly.', 'Avoid unexcised family land ("Omo Onile") by buying directly from established developers with verified titles.'],
  false
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  category = EXCLUDED.category,
  category_label = EXCLUDED.category_label,
  read_time = EXCLUDED.read_time,
  date = EXCLUDED.date,
  author = EXCLUDED.author,
  image = EXCLUDED.image,
  excerpt = EXCLUDED.excerpt,
  content = EXCLUDED.content,
  sections = EXCLUDED.sections,
  key_takeaways = EXCLUDED.key_takeaways,
  featured = EXCLUDED.featured,
  updated_at = NOW();

INSERT INTO public.articles (
  id, title, category, category_label, read_time, date, author,
  image, excerpt, content, sections, key_takeaways, featured
) VALUES (
  'inside-appleton-enclave',
  'Inside Appleton Enclave: Construction Milestones & Design Philosophy',
  'building-news',
  'Building News',
  '5 min read',
  'Feb 10, 2025',
  '{"name":"Caih Group","avatarInitials":"CG","role":"Caih Group"}'::jsonb,
  '/images/regenerated_image_1791992506306.png',
  'An insider look at structural engineering, foundation piling, luxury terrace finishes, and handover timelines at Appleton Enclave in Idera.',
  ARRAY['Construction at Appleton Enclave in Idera has achieved critical structural milestones. Our civil engineering teams have successfully concluded reinforced concrete slab casting for all Phase 1 terrace rows and are currently progressing internal mechanical, electrical, and plumbing (MEP) installations.', 'Our architectural design philosophy combines contemporary Scandinavian minimalism with the climatic demands of coastal Lagos: 3.2-meter ceiling clearances for superior natural cooling, extensive cross-ventilation, and dedicated conduit piping for smart home automation.', 'Using high-grade structural steel and anti-corrosive concrete additives, every home at Appleton Enclave is built to endure for generations without moisture ingress or structural settling.', 'Deliveries remain strictly on schedule for Q4 2025 handovers, backed by our milestone-linked escrow commitments and transparent weekly engineering updates.'],
  '[{"heading":"Substructure Engineering: Raft Foundations & Coastal Ground Stabilization","paragraphs":["Given the coastal geography of the Lekki-Epe corridor, structural longevity depends entirely on substructure integrity. At Appleton Enclave, extensive soil geotechnical tests were conducted before excavation.","Each foundation utilizes deeply reinforced raft beam networks with vapor barrier membranes and high-density aggregate concrete. This prevents capillary moisture migration and guarantees complete resistance against seasonal groundwater pressure."],"keyPoints":["Soil geotechnical test reports verified and certified by certified civil structural engineers","High-yield rebar reinforcement exceeding standard Nigerian building code requirements","Dual-layer bituminous waterproofing applied to all below-grade foundation perimeters"]},{"heading":"Internal Spatial Planning: 4-Bedroom Smart Terraces","paragraphs":["Each terrace unit at Appleton Enclave features four en-suite bedrooms, an expansive open-plan lounge, an executive family lounge on the first floor, and an attached en-suite staff quarters (BQ).","Kitchens are designed for culinary functionality, featuring scratch-resistant quartz worktops, concealed extraction ducting, soft-close German-engineered cabinetry, and dedicated utility pantries."],"keyPoints":["Floor-to-ceiling double-glazed tempered glass windows for abundant natural daylight","Pre-wired conduits for solar inverter integration, fiber optic broadband, and CCTV systems","Premium Italian porcelain floor tiling throughout living and bedroom quarters"]},{"heading":"Estate Infrastructure: Paved Roads, Solar Lighting & 24/7 Security","paragraphs":["Appleton Enclave is designed as a fully sovereign gated community. Residents will not experience the typical public utility failures common across secondary Lagos neighborhoods.","The estate features heavy-duty interlocking concrete paved road networks, deep subterranean drainage conduits, automated access control barriers, solar-powered LED street illumination, and a central water purification station."]}]'::jsonb,
  ARRAY['Reinforced raft foundations engineered specifically for coastal soil stability and longevity.', 'Spacious 4-bedroom terrace homes with en-suite staff quarters and smart home wiring.', 'Independent estate utilities: covered drainage, solar street lighting, and central water treatment.', 'On track for scheduled Q4 2025 handovers with milestone-certified inspections available.'],
  false
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  category = EXCLUDED.category,
  category_label = EXCLUDED.category_label,
  read_time = EXCLUDED.read_time,
  date = EXCLUDED.date,
