  image = EXCLUDED.image,
  excerpt = EXCLUDED.excerpt,
  content = EXCLUDED.content,
  sections = EXCLUDED.sections,
  key_takeaways = EXCLUDED.key_takeaways,
  featured = EXCLUDED.featured,
  updated_at = NOW();

INSERT INTO public.articles (
  id, title, category, category_label, read_time, date, author,
  image, excerpt, content, sections, key_takeaways, featured
) VALUES (
  'three-steps-check-documents',
  '3 Easy Steps to Check Property Documents in Nigeria Before You Pay',
  'buying-tips',
  'Buying Tips',
  '5 min read',
  'Jan 28, 2025',
  '{"name":"Caih Group","avatarInitials":"CG","role":"Caih Group"}'::jsonb,
  'https://lh3.googleusercontent.com/aida-public/AB6AXuCnCZB9i3w6wY-79yplV3BsnJQDGuaMW_2RVge11NiznHJ0gZBg2H0evgEFiVqefXkN_OIoHKsj7Q7JoznSh9aVpvOpBqiVcnO9XLSj4o5XPoTheHl7SwR9ut_ABTGZi6NNeVMCUkyHvtn7dFoOlBPRoqXujhCc3513EwGwSwvjmBvOzD1XS7KuATqeuoF4239gBuJXTm9V3RAO_cm0mdQz2AIGfEvOkp8oqzoqLeZ5solI12E7kxsbvg',
  'A practical, straightforward checklist on how Governor’s Consent, C of O, and survey plans protect your capital against property fraud.',
  ARRAY['Navigating property documentation in Nigeria can feel overwhelming, but it follows a clear, logical verification sequence when understood. Following these three practical steps will help you confirm the legal standing of any plot or home before making financial commitments.', 'Step 1: Check the Survey Plan Coordinates. Request the official survey plan from the seller. The survey contains specific GPS beacon coordinates that identify the exact perimeter of the parcel. Take these coordinates to the Surveyor General’s office to confirm the land is free from committed government acquisition.', 'Step 2: Inspect the Root of Title. Verify whether the property has a Certificate of Occupancy (C of O), an official Gazette, or a registered Governor’s Consent. A legitimate title guarantees that the Lagos State Government recognizes the land ownership rights.', 'Step 3: Review the Contract of Sale and Developer Escrow Terms. Reputable developers link payments directly to verifiable construction stages, providing transparency and eliminating project abandonment risks.'],
  '[{"heading":"1. What Differentiates a Red Copy Survey from a Provisional Survey?","paragraphs":["A provisional survey is merely an unregistered sketch that carries no legal weight in Nigerian courts. Always demand a registered \"Red Copy\" survey plan, stamped and lodged with the State Surveyor General’s Record Office.","The Red Copy guarantees that the land coordinates have been cross-checked against state cadastral maps and do not overlap with public utility reservations or neighboring registered boundaries."],"keyPoints":["Look for the Surveyor General’s official stamp and registration numbers","Check that the surveyor’s seal and date are genuine and legible","Cross-reference the coordinates on ground with handheld GPS devices during physical inspection"]},{"heading":"2. Understanding the Hierarchy of Land Titles in Lagos","paragraphs":["Not all property titles offer identical legal protection. Understanding the hierarchy helps you calculate risk and avoid expensive legal entanglements:","1. Certificate of Occupancy (C of O): Issued directly by the State Governor, leasing state land for a 99-year term.\n2. Governor’s Consent: The mandatory legal endorsement required whenever property with a C of O or historical title is sold or transferred to a new owner.\n3. Excision & Gazette: Official state publication releasing ancestral land back to indigenous communities, making subsequent individual sales legal."],"keyPoints":["Governor’s Consent provides 100% bankable security for resale and collateralization","Avoid unapproved layouts or properties marketed solely with \"receipt and survey\"","Ensure the title document names the corporate developer or assigns direct power of attorney"]},{"heading":"3. Securing Your Purchase Through Milestone Contracts","paragraphs":["When buying off-plan homes, never pay 100% upfront. Ensure your Contract of Sale specifies staged payments tied to verifiable milestones: foundation completion, carcase decking, roof installation, and internal finishes.","At Caih Group, every payment plan is milestone-linked. Buyers inspect work at each phase before the next installment is due, ensuring complete peace of mind."]}]'::jsonb,
  ARRAY['Insist on a registered Red Copy survey plan lodged at the Surveyor General’s office.', 'Governor’s Consent and C of O are the most secure, bankable property titles in Lagos.', 'Never pay 100% upfront for off-plan properties; demand milestone-linked payment schedules.', 'Caih Group provides full transparency with verifiable titles and structured payment milestones.'],
  false
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  category = EXCLUDED.category,
  category_label = EXCLUDED.category_label,
  read_time = EXCLUDED.read_time,
  date = EXCLUDED.date,
