  excerpt = EXCLUDED.excerpt,
  content = EXCLUDED.content,
  sections = EXCLUDED.sections,
  key_takeaways = EXCLUDED.key_takeaways,
  featured = EXCLUDED.featured,
  updated_at = NOW();

INSERT INTO public.articles (
  id, title, category, category_label, read_time, date, author,
  image, excerpt, content, sections, key_takeaways, featured
) VALUES (
  'governors-consent-vs-co-of-o',
  'Governor’s Consent vs. Certificate of Occupancy (C of O): Understanding Lagos Land Titles',
  'buying-tips',
  'Buying Tips',
  '6 min read',
  'Dec 18, 2024',
  '{"name":"Caih Group","avatarInitials":"CG","role":"Caih Group"}'::jsonb,
  'https://lh3.googleusercontent.com/aida-public/AB6AXuCH98qz3hJJWxr6Cvud_k8b-BNisFlBDXwgOqw9ioesdnfBm5EtGgnDsDrerr5fv2fzJlz5PwSFijZGx5VzG28EeZAqYdc6SDAr5I4LZXt2mioYWWcSNC0EaNccQuJE7VECSLsGd8MUoKzBqGmRJwpxmZ-iMEwjYzZyL0rLcoCyxtJbGLzuUF_6sDY2QSdrxlmt6i6HtSFkF05rK7_0Zwtd6-o59CEPjWiGhD596zh4XauzNEln8VxVDA',
  'Demystifying the legal differences between a Certificate of Occupancy and Governor’s Consent under the Land Use Act of 1978.',
  ARRAY['A common misconception among prospective property buyers in Nigeria is that a Certificate of Occupancy (C of O) is the only legitimate document of title, and that Governor’s Consent is somehow secondary. In legal reality, both documents provide sovereign security under the Land Use Act of 1978.', 'Under Nigerian law, all land within a state is vested in the State Governor. A C of O represents the first formal lease grant issued by the state government for a 99-year term over previously virgin or excised land.', 'Once a C of O has been issued on a parcel, the government will never issue a second C of O on that same land. Instead, every subsequent sale, inheritance, or transfer must receive the formal consent of the Governor—known as Governor’s Consent.', 'Therefore, a property backed by a registered Governor’s Consent possesses the exact same legal validity, bankability, and dispute immunity as a primary C of O.'],
  '[{"heading":"Why Governor’s Consent Is Essential for Resale and Mortgages","paragraphs":["Section 22 of the Land Use Act clearly mandates that it is unlawful to alienate or transfer any interest in property without the express consent of the State Governor.","Without obtaining Governor’s Consent on your Deed of Assignment, your purchase remains purely equitable rather than legal. This means commercial banks cannot accept the property as collateral for loans, and state authorities cannot formally recognize you as the registered title holder."],"keyPoints":["Ensures the title is registered in your personal name or corporate entity in the Alausa Land Registry","Grants full eligibility for institutional bank mortgages and commercial financing","Protects against competing claims by previous owners or unauthorized family representatives"]},{"heading":"The Application & Stamping Process at the Lagos Lands Bureau","paragraphs":["Processing Governor’s Consent involves several sequential steps: obtaining tax clearance certificates for both parties, submitting the charted survey plan, paying stamp duties and registration fees, and securing the official executive signature.","At Caih Group, our legal desk assists all estate homeowners in completing title perfection efficiently, ensuring clean documentation from contract execution to final collection."]}]'::jsonb,
  ARRAY['A C of O is only issued once for a piece of land; all subsequent transfers require Governor’s Consent.', 'Governor’s Consent carries identical legal force, bankability, and court enforceability as a C of O.', 'Properties without Governor’s Consent cannot be used as bank collateral or registered in state books.', 'Caih Group assists buyers through the full title perfection process for complete peace of mind.'],
  false
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  category = EXCLUDED.category,
  category_label = EXCLUDED.category_label,
  read_time = EXCLUDED.read_time,
  date = EXCLUDED.date,
  author = EXCLUDED.author,
  image = EXCLUDED.image,
  excerpt = EXCLUDED.excerpt,
  content = EXCLUDED.content,
  sections = EXCLUDED.sections,
  key_takeaways = EXCLUDED.key_takeaways,
  featured = EXCLUDED.featured,
  updated_at = NOW();

INSERT INTO public.articles (
  id, title, category, category_label, read_time, date, author,
  image, excerpt, content, sections, key_takeaways, featured
) VALUES (
  'lagos-coastal-highway-real-estate-impact',
  'The Lagos-Calabar Coastal Highway: Transforming Real Estate Along the Lekki Corridor',
  'building-news',
  'Building News',
  '7 min read',
  'Nov 30, 2024',
  '{"name":"Caih Group","avatarInitials":"CG","role":"Caih Group"}'::jsonb,
  'https://lh3.googleusercontent.com/aida-public/AB6AXuDzFRpyIeLl7ogQtifHFeUSAtsbvv_RPJ1yEeAbDuPtIHdJEGVW4stbhGuTxfe_8wiEOOdKSAkBSAAOy4Mqj7urOF1NMrlFr3WHW4xTdhW0o__vJDXiVW1x3rh1PBzr7hJZ5dHq3xJUg_-AF_oCNhsjh4YZnfVme_KSBZuTFKZ1wDWCChSx5x1OXG9Hm1rsYHY2TvmAMpL6LWA4GC9sF82dAOISCIHDZ2D0nEziCKCyeXyNV0j-M5qvPA',
  'How the 700km federal coastal superhighway is unlocking multi-billion dollar capital appreciation for residential and commercial estates in Lagos.',
  ARRAY['The commencement of the Lagos-Calabar Coastal Highway represents the single largest transport infrastructure investment in West Africa’s history. Spanning over 700 kilometers, the highway begins at Ahmadu Bello Way in Victoria Island and traverses the entire Lekki coastline toward Ondo State.', 'For real estate investors, the immediate impact is a dramatic reduction in travel time between the Victoria Island financial district and emerging residential communities in Lekki Phase 2, Idera, and Ibeju-Lekki.', 'Areas that previously experienced vehicular traffic bottlenecks along the single Lekki-Epe expressway now benefit from a secondary, 10-lane federal arterial corridor with dedicated mass transit lanes.', 'Properties strategically situated along this corridor—such as Caih Group’s Appleton master-planned developments—are already experiencing unprecedented demand from institutional funds and private buyers.'],
  '[{"heading":"Accelerated Commute Times and Economic Decentralization","paragraphs":["The coastal highway effectively brings Idera and the Lekki corridor within a 25-to-35 minute high-speed transit window of Victoria Island. This connectivity dissolves the traditional distance barrier that previously held back residential development in secondary nodes.","With rapid transit access, prime waterfront and near-coastal developments are transitioning from weekend getaway retreats into permanent, high-status primary residences for corporate executives."],"keyPoints":["Direct 10-lane expressway reducing island-to-refinery transit times by over 60%","Interchanges connecting smoothly with the Lekki-Epe Expressway and regional arterial roads","Surge in commercial hospitality, retail malls, and international schools along the highway"]},{"heading":"Projected Capital Appreciation Over the Next 36 Months","paragraphs":["Historical data from similar infrastructure projects (such as the Lekki Toll Road expansion in 2008 and the Third Mainland Bridge in 1990) indicates that land values along primary infrastructure arteries appreciate by 300% to 500% within five years of construction commencement.","Investors securing residential serviced plots and off-plan terrace homes today are locking in entry pricing before the complete highway section is commissioned."]}]'::jsonb,
  ARRAY['The Lagos-Calabar Coastal Highway connects Victoria Island directly to Ibeju-Lekki in under 35 minutes.', 'Ten-lane federal superhighway providing a high-speed alternative to the Lekki-Epe expressway.', 'Land and residential values in Idera and Lekki Phase 2 projected to see massive capital appreciation.', 'Caih Group properties are positioned to maximize logistics, connectivity, and investment appreciation.'],
  false
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  category = EXCLUDED.category,
  category_label = EXCLUDED.category_label,
  read_time = EXCLUDED.read_time,
  date = EXCLUDED.date,
  author = EXCLUDED.author,
  image = EXCLUDED.image,
  excerpt = EXCLUDED.excerpt,
  content = EXCLUDED.content,
  sections = EXCLUDED.sections,
  key_takeaways = EXCLUDED.key_takeaways,
  featured = EXCLUDED.featured,
  updated_at = NOW();

